#!/usr/bin/env python3
"""Regenerates the Slint part of THIRD_PARTY_NOTICES.txt (standard library only).

port-forwarder.exe links Slint, the standalone window's toolkit, statically, and with it the
Rust crates Slint depends on for Windows x64. Their notices go into THIRD_PARTY_NOTICES.txt,
which ships in the plugin package and next to the exe. Everything from the marker line on is
generated here; everything above it is kept as it is.

    python third_party/slint/notices.py <slint checkout> [THIRD_PARTY_NOTICES.txt]

<slint checkout> is github.com/slint-ui/slint at the commit CMakeLists.txt pins
(PF_SLINT_COMMIT; the build's own copy is build/_deps/slint-src). Needs cargo-about 0.8 on
PATH (cargo install cargo-about --locked). Run it after every Slint upgrade: CMake refuses to
configure when the notices name another Slint version than the one it builds.
"""

import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
MARKER = "=== Slint and its Rust dependencies (generated by third_party/slint/notices.py) ==="
# The cargo features of slint-cpp that CMakeLists.txt turns on (SLINT_FEATURE_*), plus std.
FEATURES = "std,backend-winit,renderer-software,accessibility"
RULE = "-" * 80


def cmake_value(name):
    with open(os.path.join(ROOT, "CMakeLists.txt"), encoding="utf-8") as f:
        m = re.search(r'set\(%s "([^"]+)"\)' % name, f.read())
    if not m:
        sys.exit("CMakeLists.txt: no set(%s ...)" % name)
    return m.group(1)


def main(argv):
    if len(argv) not in (2, 3):
        print(__doc__)
        return 2
    slint = os.path.abspath(argv[1])
    out_path = argv[2] if len(argv) == 3 else os.path.join(ROOT, "THIRD_PARTY_NOTICES.txt")
    version = cmake_value("PF_SLINT_VERSION")
    commit = cmake_value("PF_SLINT_COMMIT")
    head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=slint, capture_output=True, text=True).stdout.strip()
    if head != commit:
        sys.exit("%s is at %r, CMakeLists.txt pins %s" % (slint, head, commit))

    rust = subprocess.run(
        ["cargo", "about", "generate", "--manifest-path", os.path.join(slint, "api", "cpp", "Cargo.toml"),
         "--no-default-features", "--features", FEATURES, "--locked", "--fail",
         "-c", os.path.join(HERE, "about.toml"), os.path.join(HERE, "about.hbs")],
        check=True, capture_output=True, text=True, encoding="utf-8").stdout

    with open(os.path.join(slint, "LICENSES", "LicenseRef-Slint-Royalty-free-2.0.md"), encoding="utf-8") as f:
        slint_license = f.read().strip()

    with open(out_path, encoding="utf-8") as f:
        kept = f.read()
    at = kept.find(MARKER)
    if at >= 0:
        kept = kept[:at]
    kept = kept.rstrip("\n") + "\n\n"

    part = [
        MARKER,
        "",
        RULE,
        "Slint %s" % version,
        "https://slint.dev/ -- https://github.com/slint-ui/slint (commit %s)" % commit,
        "Copyright (c) SixtyFPS GmbH",
        "Used under the Slint Royalty-free Desktop, Mobile, and Web Applications License 2.0.",
        "Attribution: the AboutSlint widget in Help > About of the standalone window.",
        RULE,
        "",
        slint_license,
        "",
        RULE,
        "The Rust crates linked into port-forwarder.exe with Slint (x86_64-pc-windows-msvc),",
        "grouped by licence text.",
        RULE,
        "",
        rust.strip(),
        "",
    ]
    text = kept + "\n".join(part)
    with open(out_path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("%s: %d bytes" % (out_path, len(text.encode("utf-8"))))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
